<?php
declare(strict_types=1);
require_once __DIR__ . '/auth.php';
adminRequireAuth();
$root=dirname(__DIR__);$file=$root.'/data/aloqa.json';$notice='';$error='';$default=['title'=>'Aloqa','intro'=>'','hero_image'=>'','contact'=>[],'social'=>[]];
function readContact(string $file,array $default):array{$raw=is_file($file)?file_get_contents($file):false;$data=is_string($raw)?json_decode($raw,true):null;if(!is_array($data))$data=$default;foreach($default as $key=>$value){if(!array_key_exists($key,$data))$data[$key]=$value;if(is_array($value)&&!is_array($data[$key]))$data[$key]=$value;}return $data;}
function jsonText(mixed $value):string{if(!is_array($value)||$value===[])return ''; $json=json_encode($value,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);return $json===false?'':$json;}
function parseJsonField(string $value,string $label):array{$value=trim($value);if($value==='')return []; $decoded=json_decode($value,true);if(!is_array($decoded))throw new RuntimeException("$label valid JSON object yoki array bo‘lishi kerak.");return $decoded;}
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$data=readContact($file,$default);
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!adminVerifyCsrf((string)($_POST['csrf']??'')))throw new RuntimeException('CSRF token noto‘g‘ri yoki sessiya eskirgan.');$title=trim((string)($_POST['title']??''));$intro=trim((string)($_POST['intro']??''));$heroImage=trim((string)($_POST['hero_image']??''));if($title==='')throw new RuntimeException('Sarlavha bo‘sh bo‘lishi mumkin emas.');if($heroImage!==''&&!preg_match('#^(?:https?://|/|\.\./|media/)#i',$heroImage))throw new RuntimeException('Hero image path xavfsiz formatda emas.');$data=['title'=>$title,'intro'=>$intro,'hero_image'=>$heroImage,'contact'=>parseJsonField((string)($_POST['contact']??''),'Contact'),'social'=>parseJsonField((string)($_POST['social']??''),'Social')];$json=json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($json===false||file_put_contents($file,$json.PHP_EOL,LOCK_EX)===false)throw new RuntimeException('JSON faylini saqlash amalga oshmadi.');$notice='Aloqa kontenti saqlandi.';}catch(Throwable $ex){$error=$ex->getMessage();}}
